package lk.gov.health.govcare.ai;
import lk.gov.health.govcare.common.*;import lk.gov.health.govcare.security.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;import static lk.gov.health.govcare.ai.CkdDtos.*;
@Service public class CkdPredictionService {
 private static final String MODEL="GOVCARE-CKD-LOGISTIC-1.0"; private final SqlSupport sql; private final JsonSupport json; private final CkdStageClassificationService stages; private final ClinicalPatientAccess access; private final ClinicalPredictionFeatureService clinicalFeatures;
 private final String[] names={"Age","BMI","SystolicBP","DiastolicBP","FastingBloodSugar","HbA1c","SerumCreatinine","BUNLevels","GFR","ProteinInUrine","ACR","SerumElectrolytesPotassium","HemoglobinLevels","Edema","FamilyHistoryKidneyDisease","PreviousAcuteKidneyInjury","NSAIDsUse"};
 private final double[] mean={54.441230,27.620049,134.392405,89.313442,132.529429,6.983682,2.753198,27.578147,66.829202,2.493736,149.881615,4.505336,13.927304,.201929,.141049,.105485,5.011715};
 private final double[] sd={20.543563,7.286473,25.760027,17.349248,36.552013,1.734191,1.316771,12.804201,30.041777,1.449258,86.824108,.583787,2.337667,.401439,.348072,.307178,2.868947};
 private final double[] coef={-.006046,.184328,.390813,.195856,.365203,.243350,.799789,.370827,-.685273,.403530,-.118598,.083778,.206338,.286131,.135394,-.018497,.015149};
 private static final Map<String,String> UNITS=Map.ofEntries(Map.entry("BMI","kg/m²"),Map.entry("SystolicBP","mmHg"),Map.entry("DiastolicBP","mmHg"),Map.entry("FastingBloodSugar","mg/dL"),Map.entry("HbA1c","%"),Map.entry("SerumCreatinine","mg/dL"),Map.entry("BUNLevels","mg/dL"),Map.entry("GFR","mL/min/1.73m²"),Map.entry("ProteinInUrine","mg/dL"),Map.entry("ACR","mg/g"),Map.entry("SerumElectrolytesPotassium","mmol/L"),Map.entry("HemoglobinLevels","g/dL"));
 public CkdPredictionService(SqlSupport s,JsonSupport j,CkdStageClassificationService stageService,ClinicalPatientAccess access){this(s,j,stageService,access,new ClinicalPredictionFeatureService(s,access,new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules()));}
 @org.springframework.beans.factory.annotation.Autowired
 public CkdPredictionService(SqlSupport s,JsonSupport j,CkdStageClassificationService stageService,ClinicalPatientAccess access,ClinicalPredictionFeatureService clinicalFeatures){sql=s;json=j;stages=stageService;this.access=access;this.clinicalFeatures=clinicalFeatures;}
 @Transactional public Map<String,Object> predict(GovCarePrincipal a,PredictionRequest q){
  if(q==null||q.patientId()==null||q.features()==null||q.requestId()==null||q.requestId().isBlank())throw ApiException.badRequest("Patient, clinical features, and request ID are required.");
  UUID patient=sql.uuid(q.patientId(),"patientId");a=access.clinicalScope(a,patient,true);Map<String,Object> patientRow=sql.required("select id,patient_no,full_name,date_of_birth from patients where id=:patient and hospital_id=:hospital and status<>'deleted'",Map.of("patient",patient,"hospital",a.hospitalId()),"Patient not found.");
  if(sql.one("select id from ai_ckd_predictions where hospital_id=:hospital and request_id=:request",Map.of("hospital",a.hospitalId(),"request",q.requestId())).isPresent()) throw ApiException.conflict("This assessment request was already processed.");
  List<Map<String,Object>> factors=new ArrayList<>(); double z=.777850; int missing=0; Map<String,Object> clean=new LinkedHashMap<>();
  for(int i=0;i<names.length;i++){BigDecimal raw=q.features().get(names[i]);if(raw==null){missing++;continue;}double v=raw.doubleValue();if(!Double.isFinite(v))throw ApiException.badRequest("Invalid clinical value for "+names[i]+".");clean.put(names[i],v);double contribution=coef[i]*((v-mean[i])/sd[i]);z+=contribution;if(Math.abs(contribution)>=.12)factors.add(Map.of("feature",names[i],"value",v,"direction",contribution>0?"INCREASES_RISK":"REDUCES_RISK","contribution",BigDecimal.valueOf(contribution).setScale(4,RoundingMode.HALF_UP),"explanation",names[i]+" contributed to the model prediction."));}
  if(missing>0)throw ApiException.unprocessable("Missing clinical values: "+missing+" required model features are not available.");
  double probability=1d/(1d+Math.exp(-z));String category=probability>=.8?"URGENT_REVIEW":probability>=.6?"HIGH":probability>=.4?"MODERATE":"LOW";double confidence=Math.abs(probability-.5)*2; CkdStageClassificationService.StageAssessment stage=stages.classify(clean.get("GFR") instanceof Number n?n.doubleValue():null);
  List<String> rec=category.equals("URGENT_REVIEW")||category.equals("HIGH")?List.of("Prompt clinician review is recommended.","Correlate with current renal function, urine findings, and clinical examination."):List.of("Continue routine clinical review and monitor renal risk factors.");
  var diseaseProbabilities=DiseaseProbabilitySnapshot.capture(probability,MODEL,Instant.now(),sql.list("select model_key,version,purpose from predictive_model_registry where model_key in (:keys) and version='not-installed'",Map.of("keys",DiseaseProbabilitySnapshot.relatedKeys())));
  Map<String,Object> p=new LinkedHashMap<>();p.put("diseaseProbabilities",json.write(diseaseProbabilities));p.put("hospital",a.hospitalId());p.put("patient",patient);p.put("probability",probability);p.put("category",category);p.put("confidence",confidence);p.put("predictedClass",probability>=.5?"1":"0");p.put("input",json.write(clean));p.put("factors",json.write(factors));p.put("recommendations",json.write(rec));p.put("model",MODEL);p.put("request",q.requestId());p.put("actor",a.id());
  UUID predictionId=UUID.fromString(String.valueOf(sql.required("insert into ai_ckd_predictions(hospital_id,patient_id,probability,risk_category,confidence,predicted_class,input_data,contributing_factors,recommendations,model_version,request_id,created_by,disease_probability_snapshot) values(:hospital,:patient,:probability,:category,:confidence,:predictedClass,cast(:input as jsonb),cast(:factors as jsonb),cast(:recommendations as jsonb),:model,:request,:actor,cast(:diseaseProbabilities as jsonb)) returning id::text",p,"Unable to save CKD assessment.").get("id")));
  Map<String,Object> ap=new HashMap<>();ap.put("id",predictionId);ap.put("h",a.hospitalId());ap.put("p",patient);ap.put("model",MODEL);ap.put("prob",probability);ap.put("cat",category);ap.put("conf",confidence);ap.put("actor",a.id());ap.put("g",stage.gCategory());ap.put("stage",stage.suggestedStage());ap.put("code",stage.suggestedIcdCode());ap.put("system",CkdStageClassificationService.ICD_SYSTEM);ap.put("display",stage.clinicalDescription());ap.put("codingStatus",stage.codingStatus());ap.put("basis",stage.basis());sql.update("insert into ai_assessments(id,hospital_id,patient_id,assessment_type,model_name,model_version,status,risk_probability,risk_category,confidence,suggested_ckd_g_category,suggested_ckd_stage,suggested_icd_code,suggested_icd_system,suggested_icd_display,coding_status,coding_basis,created_by) values(:id,:h,:p,'CKD_RISK_ASSESSMENT','GovCare CKD Logistic',:model,'COMPLETED',:prob,:cat,:conf,:g,:stage,:code,:system,:display,:codingStatus,:basis,:actor)",ap);
  persistInputs(a,patient,predictionId,q);clinicalFeatures.capture(a,patient,predictionId);persistFactors(predictionId,factors);for(int i=0;i<rec.size();i++)sql.update("insert into ai_assessment_recommendations(assessment_id,sequence_no,recommendation_text) values(:a,:n,:t)",Map.of("a",predictionId,"n",i+1,"t",rec.get(i)));
  persistFhir(a,patient,patientRow,predictionId,probability,category,confidence,factors,rec,stage);
  Map<String,Object> out=new LinkedHashMap<>();out.put("predictionId",predictionId.toString());out.put("patientId",q.patientId());out.put("modelVersion",MODEL);out.put("predictedClass",probability>=.5?"1":"0");out.put("probability",probability);out.put("riskCategory",category);out.put("confidence",confidence);out.put("importantFactors",factors);out.put("recommendedActions",rec);out.put("diseaseProbabilities",diseaseProbabilities);out.put("ckdStage",stage.suggestedStage());out.put("ckdGCategory",stage.gCategory());out.put("suggestedIcdCode",stage.suggestedIcdCode());out.put("suggestedIcdSystem",CkdStageClassificationService.ICD_SYSTEM);out.put("suggestedIcdDisplay",stage.clinicalDescription());out.put("codingBasis",stage.basis());out.put("codingStatus",stage.codingStatus());out.put("confirmationStatus",stage.confirmationStatus());out.put("createdAt",Instant.now().toString());out.put("disclaimer","Clinical decision support only. This output does not replace professional medical judgment.");return out;
 }
 private void persistInputs(GovCarePrincipal a,UUID patient,UUID assessment,PredictionRequest q){
  Map<String,Map<String,Object>> sources=q.sources()==null?Map.of():q.sources();
  for(String feature:names){BigDecimal raw=q.features().get(feature);if(raw==null)continue;Map<String,Object> meta=sources.getOrDefault(feature,Map.of());String source=Objects.toString(meta.get("source"),feature.equals("Age")?"CALCULATED":"MANUAL");UUID reportId=uuidOrNull(meta.get("reportId"));UUID observation=findObservation(a,patient,reportId,feature,raw.doubleValue());
   if(observation==null&&(source.equals("MANUAL")||source.equals("MANUAL_OVERRIDE")||source.equals("CALCULATED"))){UUID original=source.equals("MANUAL_OVERRIDE")?findLatestObservation(a,patient,reportId,feature):null;observation=UUID.randomUUID();Map<String,Object> op=new HashMap<>();op.put("id",observation);op.put("h",a.hospitalId());op.put("p",patient);op.put("feature",feature);op.put("display",feature);op.put("value",raw);op.put("unit",UNITS.get(feature));op.put("source",source);op.put("override",source.equals("MANUAL_OVERRIDE"));op.put("original",original);op.put("actor",a.id());op.put("effective",ClinicalMeasurementDates.explicit(meta.get("clinicalDate")));sql.update("insert into clinical_observations(id,hospital_id,patient_id,feature_key,display_name,value_numeric,unit,normalized_value,normalized_unit,source_type,manual_override,original_observation_id,created_by,effective_at) values(:id,:h,:p,:feature,:display,:value,:unit,:value,:unit,:source,:override,:original,:actor,:effective)",op);}
   Map<String,Object> ip=new HashMap<>();ip.put("a",assessment);ip.put("feature",feature);ip.put("obs",observation);ip.put("value",raw);ip.put("unit",UNITS.get(feature));ip.put("source",source);ip.put("report",reportId);ip.put("override",source.equals("MANUAL_OVERRIDE"));ip.put("meta",json.write(meta));sql.update("insert into ai_assessment_inputs(assessment_id,feature_key,observation_id,value_numeric,unit,source_type,source_report_id,manual_override,source_metadata) values(:a,:feature,:obs,:value,:unit,:source,:report,:override,cast(:meta as jsonb))",ip);
  }
 }
 private UUID findObservation(GovCarePrincipal a,UUID patient,UUID report,String feature,double value){if(report==null)return null;return sql.one("select id::text from clinical_observations where hospital_id=:h and patient_id=:p and report_id=:r and feature_key=:f and value_numeric=:v order by created_at desc limit 1",Map.of("h",a.hospitalId(),"p",patient,"r",report,"f",feature,"v",BigDecimal.valueOf(value))).map(x->UUID.fromString(String.valueOf(x.get("id")))).orElse(null);}
 private UUID findLatestObservation(GovCarePrincipal a,UUID patient,UUID report,String feature){if(report==null)return null;return sql.one("select id::text from clinical_observations where hospital_id=:h and patient_id=:p and report_id=:r and feature_key=:f order by created_at desc limit 1",Map.of("h",a.hospitalId(),"p",patient,"r",report,"f",feature)).map(x->UUID.fromString(String.valueOf(x.get("id")))).orElse(null);}
 private void persistFactors(UUID assessment,List<Map<String,Object>> factors){for(Map<String,Object> f:factors){Map<String,Object> p=new HashMap<>();String feature=Objects.toString(f.get("feature"));p.put("a",assessment);p.put("feature",feature);p.put("display",feature);p.put("value",f.get("value"));p.put("unit",UNITS.get(feature));p.put("direction",f.get("direction"));p.put("contribution",f.get("contribution"));p.put("explanation",f.get("explanation"));sql.update("insert into ai_assessment_factors(assessment_id,feature_key,display_name,input_value,unit,contribution_direction,contribution_value,explanation) values(:a,:feature,:display,:value,:unit,:direction,:contribution,:explanation)",p);}}
 private void persistFhir(GovCarePrincipal a,UUID patient,Map<String,Object> patientRow,UUID assessment,double probability,String category,double confidence,List<Map<String,Object>> factors,List<String> rec,CkdStageClassificationService.StageAssessment stage){
  String patientFhir=sql.one("select resource_id from fhir_resource where hospital_id=:h and patient_id=:p and resource_type='Patient' order by created_date limit 1",Map.of("h",a.hospitalId(),"p",patient)).map(x->String.valueOf(x.get("resource_id"))).orElse(null);
  if(patientFhir==null){patientFhir="patient-"+patient;String pj="{\"resourceType\":\"Patient\",\"id\":\""+patientFhir+"\",\"identifier\":[{\"system\":\"urn:govcare:patient-number\",\"value\":\""+esc(Objects.toString(patientRow.get("patient_no"),""))+"\"}],\"name\":[{\"text\":\""+esc(Objects.toString(patientRow.get("full_name"),""))+"\"}]}";storeFhir(a,patient,"Patient",patientFhir,pj);}
  String riskId="ckd-risk-"+assessment;String rationale=esc("GovCare CKD AI model "+MODEL+"; confidence "+BigDecimal.valueOf(confidence).setScale(4,RoundingMode.HALF_UP));String rj="{\"resourceType\":\"RiskAssessment\",\"id\":\""+riskId+"\",\"status\":\"final\",\"subject\":{\"reference\":\"Patient/"+patientFhir+"\"},\"occurrenceDateTime\":\""+Instant.now()+"\",\"prediction\":[{\"outcome\":{\"text\":\"CKD risk - "+category+"\"},\"probabilityDecimal\":"+probability+",\"qualitativeRisk\":{\"text\":\""+category+"\"},\"rationale\":\""+rationale+"\"}]}";storeFhir(a,patient,"RiskAssessment",riskId,rj);
  String ciId="ckd-impression-"+assessment;String finding=stage.suggestedIcdCode()==null?"":",\"finding\":[{\"itemCodeableConcept\":{\"coding\":[{\"system\":\""+CkdStageClassificationService.ICD_SYSTEM+"\",\"code\":\""+esc(stage.suggestedIcdCode())+"\",\"display\":\""+esc(Objects.toString(stage.clinicalDescription(),""))+"\"}],\"text\":\"AI-assisted CKD classification; clinician confirmation required\"}}]";String cj="{\"resourceType\":\"ClinicalImpression\",\"id\":\""+ciId+"\",\"status\":\"completed\",\"subject\":{\"reference\":\"Patient/"+patientFhir+"\"},\"date\":\""+Instant.now()+"\",\"summary\":\"AI decision support: "+category+" CKD risk; "+esc(Objects.toString(stage.suggestedStage(),"stage unavailable"))+" coding assistance. Clinician review required.\",\"description\":\"Generated by "+MODEL+"; this is not a confirmed diagnosis.\""+finding+"}";storeFhir(a,patient,"ClinicalImpression",ciId,cj);
 }
 private void storeFhir(GovCarePrincipal a,UUID patient,String type,String id,String body){sql.update("insert into fhir_resource(resource_type,resource_id,patient_id,hospital_id,json_data) values(:t,:id,:p,:h,cast(:j as jsonb)) on conflict(hospital_id,resource_type,resource_id) do update set version=fhir_resource.version+1,json_data=excluded.json_data,updated_date=now()",Map.of("t",type,"id",id,"p",patient,"h",a.hospitalId(),"j",body));}
 public List<Map<String,Object>> patients(GovCarePrincipal a,String search){var visible=access.visiblePatientIds(a);if(visible.isEmpty())return List.of();String q=search==null?"":search.trim().toLowerCase(Locale.ROOT);return sql.list("select id::text,patient_no,full_name,date_of_birth,gender::text,nic,profile_photo_url,updated_at from patients where hospital_id=:hospital and id in (:visible) and status<>'deleted' and (:q='' or lower(patient_no) like :like or lower(full_name) like :like or lower(coalesce(nic,'')) like :like) order by updated_at desc limit 50",Map.of("hospital",a.hospitalId(),"visible",visible,"q",q,"like","%"+q+"%"));}
 public List<Map<String,Object>> history(GovCarePrincipal a,String patientId){a=access.clinicalScope(a,sql.uuid(patientId,"patientId"),false);return sql.list("select p.id::text \"predictionId\",p.probability,p.risk_category \"riskCategory\",p.confidence,p.predicted_class \"predictedClass\",p.model_version \"modelVersion\",p.input_data \"inputData\",p.contributing_factors \"importantFactors\",p.recommendations \"recommendedActions\",p.created_at \"createdAt\",p.disease_probability_snapshot \"diseaseProbabilities\",coalesce(a.review_status,'AWAITING_REVIEW') \"reviewStatus\" from ai_ckd_predictions p left join ai_assessments a on a.id=p.id where p.hospital_id=:hospital and p.patient_id=cast(:patient as uuid) order by p.created_at desc limit 50",Map.of("hospital",a.hospitalId(),"patient",patientId));}
 public Map<String,Object> assessment(GovCarePrincipal a,UUID id){a=assessmentScope(a,id,false);var row=sql.required("select patient_id from ai_ckd_predictions where id=:id and hospital_id=:h",Map.of("id",id,"h",a.hospitalId()),"CKD assessment not found.");access.requireClinical(a,(UUID)row.get("patient_id"));return sql.required("select p.id::text \"predictionId\",p.patient_id::text \"patientId\",p.probability,p.risk_category \"riskCategory\",p.confidence,p.predicted_class \"predictedClass\",p.model_version \"modelVersion\",p.input_data \"inputData\",p.contributing_factors \"importantFactors\",p.recommendations \"recommendedActions\",p.created_at \"createdAt\",p.disease_probability_snapshot \"diseaseProbabilities\",coalesce(a.review_status,'AWAITING_REVIEW') \"reviewStatus\" from ai_ckd_predictions p left join ai_assessments a on a.id=p.id where p.id=:id and p.hospital_id=:h",Map.of("id",id,"h",a.hospitalId()),"CKD assessment not found.");}
 public GovCarePrincipal assessmentScope(GovCarePrincipal a,UUID id,boolean write){
  Map<String,Object> params=new HashMap<>();params.put("id",id);params.put("h",a.hospitalId());params.put("network",access.canAccessNetwork(a));
  var row=sql.required("select patient_id from ai_ckd_predictions where id=:id and (:network or hospital_id=:h)",params,"CKD assessment not found.");
  return access.clinicalScope(a,(UUID)row.get("patient_id"),write);
 }
 public Map<String,Object> patient(GovCarePrincipal a,UUID id){a=access.clinicalScope(a,id,false);return sql.required("select p.id::text,p.hospital_id::text,p.patient_no,p.full_name,p.date_of_birth,p.gender::text,p.nic,p.profile_photo_url,p.updated_at,h.name hospital_name,h.code hospital_code from patients p join hospitals h on h.id=p.hospital_id where p.id=:p and p.hospital_id=:h and p.status<>'deleted'",Map.of("p",id,"h",a.hospitalId()),"Patient not found.");}
 private static UUID uuidOrNull(Object v){try{return v==null?null:UUID.fromString(String.valueOf(v));}catch(Exception e){return null;}}private static String esc(String s){return s.replace("\\","\\\\").replace("\"","\\\"");}
}
